def design(feats):
    X = np.asarray(feats.x, float); y = np.asarray(feats.y, float); n, p = X.shape
    ids = list(feats.ids); labs = sorted(set(feats.stratum))
    S = np.array([[s == l for l in labs[1:]] for s in feats.stratum], float).reshape(n, -1)
    base = np.column_stack([np.ones(n), S])
    def ll(Z):
        A = np.column_stack([base, Z]) if Z is not None and len(Z) else base
        b = np.zeros(A.shape[1])
        for _ in range(30):
            eta = np.clip(A @ b, -30, 30); m = 1 / (1 + np.exp(-eta)); w = m * (1 - m) + 1e-9
            H = A.T @ (A * w[:, None]) + 1e-6 * np.eye(A.shape[1])
            st = np.linalg.solve(H, A.T @ (y - m)); b += st
            if np.max(np.abs(st)) < 1e-8: break
        m = np.clip(1 / (1 + np.exp(-np.clip(A @ b, -30, 30))), 1e-12, 1 - 1e-12)
        return float(np.sum(y * np.log(m) + (1 - y) * np.log(1 - m)))
    def cols(sel, extra=()):
        z = [X[:, j] for j in sel] + [X[:, a] * X[:, b] for a, b in extra]
        return np.column_stack(z) if z else None
    R = np.corrcoef(X.T); R = np.nan_to_num(R)
    sel = []; cur = ll(None)
    for k in range(MAX_DRIVERS):
        best = None
        for j in range(p):
            if j in sel or any(abs(R[j, s]) >= 0.6 for s in sel): continue
            v = ll(cols(sel + [j]))
            if best is None or v > best[0]: best = (v, j)
        if best is None or stats.chi2.sf(2 * (best[0] - cur), 1) > 0.1 / p: break
        v, j = best
        clus = [c for c in range(p) if abs(R[j, c]) >= 0.6 and c not in sel and not any(abs(R[c, s]) >= 0.6 for s in sel)]
        if len(clus) > 1:
            lls = {c: ll(cols(sel + [c])) for c in clus}
            j = max([c for c in clus if lls[c] >= v - 2], key=lambda c: sum(R[c, d] ** 2 for d in clus)); v = lls[j]
        sel.append(j); cur = v
    changed = True
    while changed and sel:
        changed = False
        for j in list(sel):
            rest = [s for s in sel if s != j]
            if stats.chi2.sf(2 * (cur - ll(cols(rest))), 1) > 0.05 / p:
                sel = rest; cur = ll(cols(sel)); changed = True; break
    pairs = [(a, b) for a in range(p) for b in range(a, p)]
    Pc = np.column_stack([X[:, a] * X[:, b] for a, b in pairs]); Pc -= Pc.mean(0)
    r0 = y - y.mean(); sc = (Pc.T @ r0) ** 2 / (np.sum(Pc ** 2, 0) * y.mean() * (1 - y.mean()) + 1e-12)
    cand = []
    for i in np.argsort(-sc)[:15]:
        a, b = pairs[i]; mains = sorted(set(sel) | {a, b})
        pv = stats.chi2.sf(2 * (ll(cols(mains, [(a, b)])) - ll(cols(mains))), 1)
        if pv < 0.01 / len(pairs): cand.append((pv, a, b))
    prods = []
    for pv, a, b in sorted(cand):
        if len(prods) < 2 and not any({a, b} & {c, d} for c, d in prods): prods.append((a, b))
    msel = list(dict.fromkeys(list(sel) + [c for a, b in prods for c in (a, b)]))
    if prods:
        for c in list(msel):
            if c in sel: continue
            rest = [s for s in msel if s != c]
            if stats.chi2.sf(2 * (ll(cols(msel, prods)) - ll(cols(rest, prods))), 1) > 0.01 / p: msel = rest
    drivers = list(dict.fromkeys(list(sel) + [c for a, b in prods for c in (a, b)]))[:MAX_DRIVERS]
    loads = {}
    adj = np.abs(R) >= 0.7; np.fill_diagonal(adj, False)
    core = np.flatnonzero(adj.sum(1) >= 3)
    comp = sorted(set(core.tolist()) | {int(j) for i in core for j in np.flatnonzero(adj[i])})
    def pc(Z):
        s = Z @ np.linalg.eigh(np.nan_to_num(np.corrcoef(Z.T)))[1][:, -1]
        return (s - s.mean()) / (s.std() + 1e-9)
    if len(comp) >= 5:
        sc1 = pc(X[:, comp])
        if stats.chi2.sf(2 * (ll(sc1[:, None]) - ll(None)), 1) < 0.3:
            v1 = np.linalg.eigh(np.nan_to_num(np.corrcoef(X[:, comp].T)))[1][:, -1]
            loads = {ids[c]: float(v1[k] / np.sum(np.abs(v1))) for k, c in enumerate(comp)}
            add = max(ll(np.column_stack([pc(X[:, [c for c in comp if c != m]]), X[:, m]])) - ll(pc(X[:, [c for c in comp if c != m]])[:, None]) for m in comp)
            if stats.chi2.sf(2 * add, 1) > 0.02:
                drivers = ([j for j in drivers if j not in comp] + sorted(comp, key=lambda c: -ll(cols([c]))))[:MAX_DRIVERS]
                msel = [j for j in msel if j not in comp]
    return Design(drivers=tuple(ids[j] for j in drivers), columns=tuple(ids[j] for j in msel),
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings=loads)

